import {humanize,validId,validateSnapshot,aggregate,inventoryRows,compareMaterials,materialsCsv,MAX_COUNT,CONTAINER_KINDS,STORAGE_KINDS,containerKind,sourceScope,filterContainers} from './core.js';
import {demoSnapshot,demoTargets,demoProjects} from './demo.js';
import {itemIcons} from './item-icons.js';
import {parseMaterialList} from './schematic.js';
import {planMaterials,craftingCsv} from './recipes.js';
import {recipeCatalogs} from './recipes-data.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>new Intl.NumberFormat('en-US').format(n);
const pixelPaths={search:'M2 2h8v2H2zM0 4h2v6H0zM10 4h2v6h-2zM2 10h8v2H2zM10 12h2v2h-2zM12 14h4v2h-4z',arrow:'M1 7h10V3h2v2h2v2h1v2h-1v2h-2v2h-2V9H1z',download:'M7 1h2v8h3v2h-2v2H6v-2H4V9h3zM1 12h2v2h10v-2h2v4H1z',upload:'M6 1h4v2h2v2H9v8H7V5H4V3h2zM1 12h2v2h10v-2h2v4H1z',plus:'M7 2h2v5h5v2H9v5H7V9H2V7h5z',close:'M2 2h2v2H2zm2 2h2v2H4zm2 2h4v4H6zm4-2h2v2h-2zm2-2h2v2h-2zM4 10h2v2H4zm-2 2h2v2H2zm8-2h2v2h-2zm2 2h2v2h-2z',chevron:'M5 2h2v2H5zm2 2h2v2H7zm2 2h2v4H9zm-2 4h2v2H7zm-2 2h2v2H5z',check:'M12 2h2v4h-2zm-2 4h2v2h-2zM8 8h2v2H8zM6 10h2v2H6zM4 8h2v2H4zM2 6h2v2H2z',menu:'M1 2h14v2H1zm0 5h14v2H1zm0 5h14v2H1z',copy:'M1 1h9v2H3v8H1zm4 4h10v10H5zm2 2v6h6V7z',trash:'M5 1h6v2h4v2H1V3h4zM3 6h2v7h6V6h2v9H3zM7 6h2v6H7z',sliders:'M2 1h2v4H2zm0 10h2v4H2zM0 5h6v6H0zm8-4h2v9H8zm0 13h2v1H8zM6 10h6v4H6zm8-9h2v3h-2zm0 9h2v5h-2zM12 4h4v6h-4z',info:'M2 0h12v2H2zM0 2h2v12H0zM14 2h2v12h-2zM2 14h12v2H2zM7 3h2v2H7zm0 4h2v6H7z',external:'M9 0h7v7h-2V3l-6 6-1-2 6-5H9zM0 3h6v2H2v9h9v-4h2v6H0z',refresh:'M3 2h8v2H3zM1 4h2v7H1zm2 7h8v2H3zm8-7h2v5h-6V7h4z'};
const gameIcons={grid:'crafting_table',box:'chest',layers:'iron_ingot',hammer:'iron_pickaxe',pin:'compass',alert:'redstone_torch',clock:'clock',leaf:'oak_sapling',file:'paper',cube:'grass_block',spark:'book',link:'redstone',ender:'ender_pearl',barrel:'barrel',shulker:'shulker_box'};
const icon=(name,size=17)=>gameIcons[name]?`<img class="game-ui-icon" src="./items/${gameIcons[name]}.png" width="${size}" height="${size}" alt="" aria-hidden="true">`:`<svg width="${size}" height="${size}" viewBox="0 0 16 16" fill="currentColor" shape-rendering="crispEdges" aria-hidden="true"><path d="${pixelPaths[name]||pixelPaths.info}" fill-rule="evenodd"/></svg>`;
function itemArt(id){return `<img class="minecraft-item" src="${esc(itemIcons[id]||'./ui/unknown.svg')}" alt="" loading="lazy" width="32" height="32">`;}
const itemImage=id=>`<span class="item-image">${itemArt(id)}</span>`;
let persistenceError=false;
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function writeLocal(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{persistenceError=true;toast('Browser storage is full or unavailable. Export your changes before closing.');return false;}}
const local=/^(127\.0\.0\.1|localhost)$/.test(location.hostname)&&/^194(?:8[2-9]|9[0-2])$/.test(location.port);
let token='';
try{
  token=new URLSearchParams(location.hash.slice(1)).get('token')||sessionStorage.getItem('stockpile-token')||'';
  if(token){sessionStorage.setItem('stockpile-token',token);history.replaceState(null,'',location.pathname+location.search);}
}catch{}
let restored=readLocal('stockpile-inventory',null);
try{if(restored)restored=validateSnapshot(restored);}catch{restored=null;}
let savedProjects=readLocal('stockpile-projects',[]);
if(!Array.isArray(savedProjects))savedProjects=[];
savedProjects=savedProjects.filter(p=>{try{parseMaterialList(JSON.stringify(p),'.json');return typeof p.id==='string';}catch{return false;}}).slice(0,50);
const state={view:'overview',source:local?'local':restored?'import':'demo',data:local?{schemaVersion:1,capturedAt:0,connected:false,worlds:[]}:restored||validateSnapshot(demoSnapshot),worldId:'',dimension:'all',query:'',filter:'all',sort:'count',limit:20,projects:savedProjects,selectedProject:'',copies:1,missingOnly:false,registry:null,syncError:'',uploadError:'',busy:false,mobile:false,recipeSubstitutions:readLocal('stockpile-recipe-substitutions',false)===true,recipeVersion:['26.2','26.3'].includes(readLocal('stockpile-recipe-version','26.3'))?readLocal('stockpile-recipe-version','26.3'):'26.3',includePacked:readLocal('stockpile-include-packed',true)!==false,containerKinds:(Array.isArray(readLocal('stockpile-container-kinds',STORAGE_KINDS))?readLocal('stockpile-container-kinds',STORAGE_KINDS):STORAGE_KINDS).filter(k=>CONTAINER_KINDS.includes(k))};
state.worldId=state.data.worlds[0]?.id||'';
let toastTimer;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function world(){return state.data.worlds.find(w=>w.id===state.worldId)||{id:'',name:'No world yet',containers:[]};}
function containers(){return filterContainers(world().containers,{kinds:state.containerKinds,dimension:state.dimension});}
function scopeLabel(){return {storage:'Storage inventory',ender:'Ender Chest',combined:'Combined inventory',none:'No containers selected'}[sourceScope(state.containerKinds)];}
function originLabel(c){return {chest:'Chest',barrel:'Barrel',shulker:'Placed shulker box',ender:'Ender Chest'}[containerKind(c)];}
function containerControls(){return `<section class="container-controls" aria-label="Container sources"><div class="source-heading"><strong>Container sources</strong><span>${scopeLabel()}</span></div><div class="container-options">${CONTAINER_KINDS.map(k=>`<label class="container-kind ${state.containerKinds.includes(k)?'selected':''}">${icon(k==='chest'?'box':k,18)}<input type="checkbox" data-container-kind="${k}" ${state.containerKinds.includes(k)?'checked':''}><span>${{chest:'Chests',barrel:'Barrels',shulker:'Placed shulkers',ender:'Ender Chest'}[k]}</span></label>`).join('')}</div><p>Ender Chest contents stay separate unless you include them here. Build checks use these selected sources.</p></section>`;}
function legacyTargetKey(){return `stockpile-targets:${state.source==='demo'?'demo':'real'}:${state.worldId}`;}
function targetKey(){return `${legacyTargetKey()}:${sourceScope(state.containerKinds)}`;}
function targets(){const fallback=sourceScope(state.containerKinds)==='storage'?readLocal(legacyTargetKey(),state.source==='demo'?demoTargets:{}):{};const data=readLocal(targetKey(),fallback);return Object.fromEntries(Object.entries(data||{}).filter(([id,n])=>validId(id)&&Number.isInteger(n)&&n>=0&&n<=MAX_COUNT));}
function inventory(){return aggregate(containers(),{includePacked:state.includePacked});}
function allRows(){return inventoryRows(containers(),targets(),{includePacked:state.includePacked});}
function packedControl(){return `<label class="packed-control"><input id="include-packed" type="checkbox" ${state.includePacked?'checked':''}>Include shulker contents</label>`;}
function scanNotes(){const missing=state.includePacked&&containers().some(c=>!c.packedItems&&c.items.some(i=>i.id.endsWith('shulker_box')));const incomplete=state.includePacked&&containers().some(c=>c.packedScanComplete===false);return `${missing?'<div class="storage-warning">This export has no shulker-content data for some chests. Update the mod and reopen those chests.</div>':''}${incomplete?'<div class="storage-warning">Some shulker contents could not be read completely. Check those containers before building.</div>':''}`;}
function projectList(){return [...state.projects,...(state.source==='demo'?demoProjects:[])];}
function project(){return projectList().find(p=>p.id===state.selectedProject)||projectList()[0];}
function recipeVersion(){return recipeCatalogs[state.data.minecraftVersion]?state.data.minecraftVersion:state.recipeVersion;}
function recipePlan(p=project(),copies=state.copies){return !p?{rows:[],steps:[],limited:false}:state.recipeSubstitutions?planMaterials(p.materials,inventory(),copies,recipeCatalogs[recipeVersion()]):{rows:compareMaterials(p.materials,inventory(),copies),steps:[],limited:false};}
function comparison(p=project()){return recipePlan(p).rows;}
function coverage(rows){const total=rows.reduce((a,r)=>a+r.needed,0),have=rows.reduce((a,r)=>a+r.allocated,0);return total?Math.floor(have/total*100):0;}
function ago(time){if(!time)return 'Never checked';const mins=Math.max(0,Math.floor((Date.now()-time)/60000));if(mins<1)return 'Just now';if(mins<60)return `${mins}m ago`;if(mins<1440)return `${Math.floor(mins/60)}h ago`;return `${Math.floor(mins/1440)}d ago`;}
function dimensionLabel(dim){return dim==='all'?'All dimensions':dim==='minecraft:overworld'?'Overworld':dim==='minecraft:the_nether'?'The Nether':dim==='minecraft:the_end'?'The End':humanize(dim);}
function statusLabel(status){return {low:'Low stock',healthy:'In stock',plenty:'Plenty',untracked:'No target'}[status];}
function stockBadge(status){return `<span class="stock ${status}"><i class="dot"></i>${statusLabel(status)}</span>`;}
function button(action,label,ico='',cls='',extra=''){return `<button class="button ${cls}" data-action="${action}" ${extra}>${ico?icon(ico,14):''}${label}</button>`;}
function nav(view,label,ico,badge=''){return `<button class="nav-item ${state.view===view?'active':''}" data-action="nav" data-view="${view}">${icon(ico)}<span>${label}</span>${badge?`<span class="badge-count">${badge}</span>`:''}</button>`;}
function render(){
  const active=document.activeElement,focusId=active?.id,selection=active?.selectionStart;
  const rows=allRows(),low=rows.filter(r=>r.status==='low').length;
  const title={overview:'Overview',inventory:'Inventory',ender:'Ender Chest',planner:'Build planner',containers:'Containers',low:'Low stock'}[state.view];
  $('#app').innerHTML=`<aside class="sidebar ${state.mobile?'open':''}" aria-label="Main navigation"><a class="brand" href="./" aria-label="Stockpile home"><img src="./logo.png" alt="Stockpile chest logo">Stockpile<small>BETA</small></a><div class="nav-label">YOUR WORKSPACE</div><nav class="nav">${nav('overview','Overview','grid')}${nav('inventory','Inventory','layers')}${nav('ender','Ender Chest','ender')}${nav('planner','Build planner','hammer')}${nav('containers','Containers','box')}<div class="nav-label">KEEP AN EYE ON</div>${nav('low','Low stock','alert',low||'')}</nav><div class="sidebar-bottom">${button('connect','Connection','link','quiet')}<div class="side-foot"><i class="dot"></i>Fabric · Minecraft 26.2 / 26.3</div></div></aside><div class="workspace"><header class="topbar"><button class="mobile-toggle" data-action="mobile" aria-label="Toggle navigation">${icon('menu',20)}</button><div class="breadcrumb">${icon('box',15)}<span class="muted">Workspace</span><span class="muted">/</span><strong>${title}</strong></div><div class="top-right"><span class="source-tag ${state.source==='local'&&!state.syncError?'live':''}"><i class="dot"></i>${state.source==='demo'?'Example data':state.source==='import'?'Imported snapshot':state.syncError?'Disconnected':state.data.trackingEnabled===false?'Tracking paused':state.data.connected?'Tracking active':'World offline'}</span><select class="world-select" id="world-select" aria-label="Selected world">${state.data.worlds.length?state.data.worlds.map(w=>`<option value="${esc(w.id)}" ${w.id===state.worldId?'selected':''}>${esc(w.name)}</option>`).join(''):'<option>No world yet</option>'}</select><span class="avatar" aria-hidden="true">DZ</span></div></header><main id="main" class="main">${persistenceError?'<div class="storage-warning">Browser storage is unavailable. Export important changes before closing.</div>':''}${state.source==='local'&&state.data.trackingEnabled===false?'<div class="storage-warning">Stockpile tracking is paused. Counts are saved snapshots. Run /stockpile start in Minecraft to resume.</div>':''}${state.syncError?`<div class="storage-warning">${icon('alert',15)}${esc(state.syncError)} ${button('connect','Reconnect','','small quiet')}</div>`:''}${state.source==='demo'?`<div class="example-note">${icon('info',13)}<span>Example inventory. <button data-action="connect">Connect your mod</button> or <button data-action="import">import your inventory</button> to view your items.</span></div>`:state.source==='import'?`<div class="example-note">${icon('clock',13)}<span>Inventory snapshot · ${esc(new Date(state.data.capturedAt||Date.now()).toLocaleString())}. Import a newer export to refresh it.</span></div>`:''}${scanNotes()}${state.view==='planner'?renderPlanner():state.view==='containers'?renderContainers():renderInventoryPage(rows,low)}<footer class="footer"><span>Unofficial Minecraft tool.</span><span>${state.source==='local'?'Local dashboard · ':'Your browser · '}Counts reflect last-opened containers. ${button('about','About the counts','','quiet small')}</span></footer></main></div><input type="file" class="hidden" id="inventory-file" accept=".json,application/json" aria-label="Import inventory snapshot"><input type="file" class="hidden" id="schematic-file" accept=".litematic,.schem,.nbt,.json,.csv" aria-label="Upload schematic">`;
  if(focusId){const field=document.getElementById(focusId);if(field){field.focus({preventScroll:true});if(typeof selection==='number'&&field.type!=='number')try{field.setSelectionRange(selection,selection);}catch{}}}
  const drop=$('#dropzone');if(drop){drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('dragging');});drop.addEventListener('dragleave',()=>drop.classList.remove('dragging'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('dragging');if(e.dataTransfer.files.length)uploadSchematic(e.dataTransfer.files[0]);});}
}
function renderInventoryPage(rows,low){
  const overview=state.view==='overview',lowView=state.view==='low';
  const total=rows.reduce((s,r)=>s+r.count,0);
  return `<div class="title-row"><div><h1>${overview?`${scopeLabel()} overview`:lowView?'Low stock':scopeLabel()}</h1><p>${overview?'Item counts, chest locations and build materials.':lowView?'Items below your minimum stock targets.':'Search item names or IDs to find their storage locations.'}</p></div><div class="button-row">${button('export','Export inventory','download','quiet')}${!local?button('import','Import inventory','upload'):''}</div></div>${containerControls()}${overview?`<div class="stats"><div class="stat"><div class="stat-label">Total items ${icon('layers',16)}</div><div class="stat-value">${num(total)}</div><div class="stat-foot">Loose items and included shulker contents</div></div><div class="stat"><div class="stat-label">Item types ${icon('cube',16)}</div><div class="stat-value">${num(rows.filter(r=>r.count>0).length)}</div><div class="stat-foot">Distinct item IDs in storage</div></div><div class="stat"><div class="stat-label">Containers ${icon('box',16)}</div><div class="stat-value">${num(containers().length)}</div><div class="stat-foot">${num(new Set(containers().map(c=>c.dimension)).size)} dimensions · last observed</div></div><div class="stat warning"><div class="stat-label">Running low ${icon('alert',16)}</div><div class="stat-value">${num(low)}</div><div class="stat-foot">${low?'Items below minimum targets':'No items below minimum targets'}</div></div></div>`:''}<section class="table-section"><div class="section-head"><h2>${overview?'Inventory':lowView?'Below target':'Items'} <span class="count-label">${lowView?low:rows.length} types</span></h2>${button('targets','Stock targets','sliders','quiet small')}</div>${renderInventoryTable(rows,overview,lowView)}</section>${overview?renderBottom():''}`;
}
function dimensionOptions(){return `<select id="dimension" class="control-select" aria-label="Dimension filter"><option value="all">All dimensions</option>${[...new Set(world().containers.map(c=>c.dimension))].map(d=>`<option value="${esc(d)}" ${state.dimension===d?'selected':''}>${esc(dimensionLabel(d))}</option>`).join('')}</select>`;}
function renderInventoryTable(all,overview,lowView){
  let rows=all.filter(r=>(!lowView||r.status==='low')&&(state.filter==='all'||r.status===state.filter)&&(!state.query||`${r.name||humanize(r.id)} ${r.id}`.toLowerCase().includes(state.query.toLowerCase())));
  rows.sort((a,b)=>state.sort==='name'?(a.name||humanize(a.id)).localeCompare(b.name||humanize(b.id)):state.sort==='low'?(a.count/(a.target||1)-b.count/(b.target||1)):b.count-a.count);
  const filteredCount=rows.length,limit=overview?7:state.limit;rows=rows.slice(0,limit);
  return `<div class="table-card"><div class="table-tools"><label class="search">${icon('search',15)}<input id="inventory-search" type="search" placeholder="Search items or an item ID…" value="${esc(state.query)}" aria-label="Search items"><kbd>/</kbd></label><div class="filter-group">${packedControl()}${!lowView?`<div class="tabs" role="group" aria-label="Stock status filter">${['all','low','plenty'].map(f=>`<button class="tab ${state.filter===f?'active':''}" data-action="filter" data-filter="${f}" aria-pressed="${state.filter===f}">${{all:'All items',low:'Low stock',plenty:'Plenty'}[f]}</button>`).join('')}</div>`:'<span class="small muted">Based on your stock targets</span>'}${dimensionOptions()}<select id="sort" class="control-select" aria-label="Sort items"><option value="count" ${state.sort==='count'?'selected':''}>Most stocked</option><option value="name" ${state.sort==='name'?'selected':''}>Name A–Z</option><option value="low" ${state.sort==='low'?'selected':''}>Lowest stock</option></select></div></div><div class="table-wrap"><table><thead><tr><th>ITEM</th><th>QUANTITY</th><th>STATUS</th><th>STOCK TARGET</th><th>LOCATION</th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="item-cell">${itemImage(r.id)}<div><button class="item-button" data-action="details" data-id="${esc(r.id)}">${esc(r.name||humanize(r.id))}</button><div class="item-sub mono">${esc(r.id)}</div></div></div></td><td><span class="number">${num(r.count)}</span><span class="stacks">${Math.floor(r.count/(r.maxStack||64))} stacks${r.count%(r.maxStack||64)?' + '+r.count%(r.maxStack||64):''}</span>${r.packedCount?`<span class="packed-note">${num(r.packedCount)} inside packed shulkers</span>`:''}${r.placedShulkerCount?`<span class="placed-note">${num(r.placedShulkerCount)} in placed shulkers</span>`:''}</td><td>${stockBadge(r.status)}</td><td><div class="target-cell ${r.status}">${r.target?`<progress value="${Math.min(r.count,r.target)}" max="${r.target}" aria-label="Stock target progress"></progress>`:''}<button class="target-button" data-action="details" data-id="${esc(r.id)}">${r.target?num(r.target):'+ Set target'}</button></div></td><td><button class="location-button" data-action="details" data-id="${esc(r.id)}">${icon('pin',12)}${r.locations.length?`${r.locations.length} ${r.locations.length===1?'container':'containers'}`:'Not in storage'}${icon('chevron',11)}</button></td></tr>`).join('')||`<tr><td colspan="5"><div class="empty">${icon(lowView?'check':'search',25)}<h3>${lowView?'No low-stock items.':!all.length?'No tracked items.':'No matching items.'}</h3><p>${lowView?'Set stock targets for items you want to keep on hand.':!all.length?'Open chests in Minecraft or import an inventory export.':'Try another item name, stock filter or dimension.'}</p>${lowView?button('targets','Set stock targets','plus','small'):!all.length?button('connect','Connect Minecraft','link','small'):button('reset-filters','Clear filters','','small')}</div></td></tr>`}</tbody></table></div><div class="table-foot"><span>Showing ${rows.length} of ${filteredCount} item types · ${esc(dimensionLabel(state.dimension))}</span>${overview?button('inventory','View inventory','arrow','quiet small'):filteredCount>state.limit?button('more','Show more','plus','quiet small'):'<span>Last observed counts</span>'}</div></div>`;
}
function renderBottom(){
  const projects=projectList().slice(0,3);
  return `<section class="saved-builds"><div class="section-head"><h2>Saved builds</h2>${button('planner','Build planner','hammer','quiet small')}</div><div class="panel">${projects.length?projects.map(p=>{const rows=recipePlan(p,1).rows,percent=coverage(rows);return `<div class="project-mini"><div class="project-art">${icon('hammer',25)}</div><button data-action="project" data-id="${esc(p.id)}"><h3>${esc(p.name)}${p.sample?'<span class="label-badge">EXAMPLE</span>':''}</h3><p>${p.materials.length} material types · ${num(rows.reduce((s,r)=>s+r.needed,0))} items</p></button><div class="project-percent">${percent}%<small>available</small></div></div>`;}).join(''):`<div class="empty"><p>No saved builds.</p>${button('upload','Upload schematic','upload','small')}</div>`}</div></section>`;
}
function recipeControls(){
  return `<section class="recipe-controls" aria-label="Recipe substitutions"><div class="recipe-control-row">${button('recipe-toggle',`Recipe substitutions: ${state.recipeSubstitutions?'ON':'OFF'}`,'hammer',state.recipeSubstitutions?'primary':'',`aria-pressed="${state.recipeSubstitutions}"`)}${recipeCatalogs[state.data.minecraftVersion]?`<span class="small muted">Vanilla ${esc(recipeVersion())} recipes</span>`:`<label class="recipe-version">Minecraft recipes <select id="recipe-version" class="control-select" aria-label="Recipe Minecraft version">${Object.keys(recipeCatalogs).map(v=>`<option value="${v}" ${v===recipeVersion()?'selected':''}>${v}</option>`).join('')}</select></label>`}</div><p>${state.recipeSubstitutions?'Counts what you can craft from the selected storage. Directly required items are reserved first.':'Checks finished materials already in storage. Turn on to include what you can craft.'}</p></section>`;
}
function renderCraftingPlan(plan){
  if(!state.recipeSubstitutions)return '';
  return `<section id="crafting-plan" class="crafting-plan"><div class="section-head"><h2>Crafting plan <span class="count-label">${plan.steps.length} ${plan.steps.length===1?'step':'steps'}</span></h2>${button('crafting-csv','Export crafting steps','download','quiet small',plan.steps.length?'':'disabled')}</div><p class="recipe-note">Vanilla crafting and stonecutting for ${esc(recipeVersion())}. Requires access to the listed workstations. Smelting, fuel and custom server recipes are excluded. Nothing is crafted automatically.</p>${plan.limited?'<div class="warning-note">Some recipe paths reached the search limit. Craftable totals may be lower than what is possible.</div>':''}${plan.steps.length?`<div class="table-card"><div class="table-wrap"><table><thead><tr><th>STEP</th><th>MAKE</th><th>USE</th><th>WORKSTATION</th></tr></thead><tbody>${plan.steps.map((step,i)=>`<tr><td class="number">${i+1}</td><td><div class="item-cell">${itemImage(step.output)}<div><strong>${num(step.count)} ${esc(humanize(step.output))}</strong><div class="item-sub">${num(step.batches)} ${step.batches===1?'batch':'batches'}</div></div></div></td><td><div class="recipe-ingredients">${step.ingredients.map(item=>`<span>${itemArt(item.id)}${num(item.count)} ${esc(humanize(item.id))}</span>`).join('')}</div></td><td>${step.station==='stonecutter'?'Stonecutter':'Crafting'}</td></tr>`).join('')}</tbody></table></div><div class="table-foot"><span>Follow the steps in order. Extra batch output can be used by later steps.</span><span>One valid plan; other recipe choices may use stock differently.</span></div></div>`:`<div class="recipe-empty">${plan.rows.some(r=>r.missing)?'No craftable substitutions found in the selected storage.':'All required items are already in storage.'}</div>`}</section>`;
}
function renderPlanner(){
  const p=project(),plan=recipePlan(p),rows=plan.rows,percent=coverage(rows),missing=rows.filter(r=>r.missing),total=rows.reduce((s,r)=>s+r.needed,0),short=rows.reduce((s,r)=>s+r.missing,0),craftable=rows.reduce((s,r)=>s+(r.craftable||0),0);
  const readiness=missing.length?`${num(short)} ${short===1?'item':'items'} missing across ${missing.length} ${missing.length===1?'material':'materials'}`:p?.warnings?.length?'Listed materials covered · review notes below':craftable?`Materials covered · craft ${num(craftable)} items first`:'All listed materials in storage';
  return `<div class="title-row"><div><h1>Build materials</h1><p>Compare schematic requirements with your stored items.</p></div>${button('upload',state.busy?'Reading file…':'Upload schematic','upload','primary',state.busy?'disabled':'')}</div>${containerControls()}${recipeControls()}<div class="planner-layout"><aside class="planner-sidebar"><div id="dropzone" class="dropzone" role="button" tabindex="0" aria-label="Upload or drop a schematic file">${icon('upload',27)}<h3>${state.busy?'Reading your schematic…':'Upload a schematic'}</h3><p>Drop a schematic here, or<br>choose a file from your device.</p>${button('upload','Choose a file','plus','small')}<div class="extensions">.LITEMATIC · .SCHEM · .NBT · .CSV · .JSON<br>Up to 25 MB · processed in your browser</div></div><div class="project-list"><div class="eyebrow">YOUR BUILDS · ${projectList().length}</div>${projectList().map(b=>`<button class="project-entry ${p?.id===b.id?'active':''}" data-action="project" data-id="${esc(b.id)}">${icon('file',17)}<span>${esc(b.name)}<small>${b.materials.length} materials${b.sample?' · example project':''}</small></span></button>`).join('')||'<p class="small muted">Uploaded builds will appear here.</p>'}</div><p class="small muted">${icon('info',12)} Materials are compared against the selected world, dimension and container sources. Builds are checked independently; stock is not reserved between builds.</p></aside><section>${state.uploadError?`<div class="warning-note" role="alert">${esc(state.uploadError)}</div>`:''}${p?`<div class="planner-intro"><div class="eyebrow">${p.sample?'EXAMPLE PROJECT':'BUILD MATERIAL CHECK'}</div><div class="planner-title"><div><h2>${esc(p.name)}</h2><p>${esc(p.filename||'Material list')} · ${num(total)} items · ${esc(scopeLabel())} · ${esc(dimensionLabel(state.dimension))}</p></div><div class="build-actions">${button('export-materials','','download','quiet icon-only','aria-label="Export material checklist" title="Export checklist"')}${!p.sample?button('delete-project','','trash','quiet icon-only','aria-label="Delete build" title="Delete build"'):''}</div></div><div class="progress-head"><span>${num(total-short)} of ${num(total)} materials ${state.recipeSubstitutions?'covered':'in storage'}${craftable?` · ${num(craftable)} to craft`:''}</span><strong>${percent}%</strong></div><progress value="${total-short}" max="${total||1}" aria-label="Materials available"></progress><div class="planner-bottom"><span class="readiness ${missing.length||p.warnings?.length?'short':''}">${icon(missing.length?'alert':p.warnings?.length?'info':'check',14)}${readiness}</span><label class="copies">Build copies <input type="number" id="copies" min="1" max="999" step="1" value="${state.copies}" aria-label="Number of copies to build"></label></div></div>${p.warnings?.length?`<div class="warning-note"><strong>Check these before building</strong><ul>${p.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:''}<div class="section-head"><h2>Material checklist <span class="count-label">${rows.length} types</span></h2>${button('missing-csv','Missing materials','download','quiet small')}</div><div class="table-card"><div class="table-tools">${packedControl()}<label class="material-filter"><input type="checkbox" id="missing-only" ${state.missingOnly?'checked':''}>Only show missing materials</label>${dimensionOptions()}</div><div class="table-wrap"><table><thead><tr><th>MATERIAL</th><th>NEED</th><th>HAVE</th>${state.recipeSubstitutions?'<th>CAN CRAFT</th>':''}<th>MISSING</th><th>STORAGE</th></tr></thead><tbody>${rows.filter(r=>!state.missingOnly||r.missing).map(r=>`<tr><td><div class="item-cell">${itemImage(r.id)}<button class="item-button" data-action="details" data-id="${esc(r.id)}">${esc(r.name||humanize(r.id))}</button></div></td><td class="number">${num(r.needed)}</td><td class="number">${num(r.available)}</td>${state.recipeSubstitutions?`<td class="number craftable-count">${num(r.craftable)}</td>`:''}<td class="number ${r.missing?'material-missing':'material-check'}">${r.missing?num(r.missing):icon('check',15)}</td><td>${!r.available&&r.craftable?'<a class="location-button" href="#crafting-plan">Crafting plan</a>':`<button class="location-button" data-action="details" data-id="${esc(r.id)}">${icon('pin',12)}Find item${icon('chevron',10)}</button>`}</td></tr>`).join('')||`<tr><td colspan="${state.recipeSubstitutions?6:5}"><div class="empty">All listed materials are covered.</div></td></tr>`}</tbody></table></div><div class="table-foot"><span>${state.source==='demo'?'Compared with example inventory':'Based on last-observed chest contents'}</span><span>${state.recipeSubstitutions?'Includes the crafting plan below':'Direct materials · recipe substitutions off'}</span></div></div>${renderCraftingPlan(plan)}`:`<div class="empty large">${icon('hammer',39)}<h3>No schematic loaded.</h3><p>Upload a schematic to find out what’s already in storage<br>and what you still need to gather.</p>${button('upload','Choose schematic','upload','primary')}</div>`}</section></div>`;
}

function renderContainers(){
  const list=containers().filter(c=>!state.query||`${c.name} ${c.position.join(' ')} ${c.dimension}`.toLowerCase().includes(state.query.toLowerCase()));
  return `<div class="title-row"><div><h1>Containers</h1><p>${containers().length} remembered containers in ${esc(world().name)}.</p></div>${button('export','Export inventory','download')}</div>${containerControls()}<div class="table-tools"><label class="search">${icon('search',15)}<input id="inventory-search" type="search" placeholder="Search chests or coordinates…" value="${esc(state.query)}" aria-label="Search containers"></label>${dimensionOptions()}</div><div class="example-note">${icon('info',13)}Move or break a chest? Remove its old record here, then open it in its new location.</div><div class="container-grid">${list.map(c=>`<article class="container-card"><div class="container-top">${icon(containerKind(c)==='ender'?'ender':containerKind(c)==='shulker'?'shulker':containerKind(c)==='barrel'?'barrel':'box',20)}<h3>${esc(c.name)}</h3>${containerKind(c)==='shulker'?'<span class="placed-badge">PLACED</span>':''}</div><p>${esc(dimensionLabel(c.dimension))} · ${esc(originLabel(c))}</p><div class="coord">${esc(c.position.join(' / '))}${button('copy-coord','','copy','quiet icon-only',`data-pos="${esc(c.position.join(' '))}" aria-label="Copy coordinates"`)}</div><p>${num([...aggregate([c],{includePacked:state.includePacked}).values()].reduce((s,i)=>s+i.count,0))} items · ${aggregate([c],{includePacked:state.includePacked}).size} types${c.packedItems?.length?' · shulker contents tracked':''}</p><div class="container-icons">${c.items.slice(0,6).map(i=>itemImage(i.id)).join('')||'<span class="small muted">Empty when last opened</span>'}</div><div class="container-foot"><span class="${Date.now()-c.lastSeen>86400000?'stale':''}">Last checked ${ago(c.lastSeen)}</span>${button('forget','','trash','quiet small',`data-id="${esc(c.id)}" aria-label="Remove saved container"`)}</div></article>`).join('')||`<div class="empty"><h3>No containers found.</h3><p>Open storage containers in Minecraft to remember them.</p></div>`}</div>`;
}
function modal(title,body){const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2>${title}</h2>${button('close','','close','quiet icon-only','aria-label="Close dialog"')}</div><div class="modal-body">${body}</div>`;if(!el.open)el.showModal();}
function connect(){modal('Minecraft connection',`<p>Stockpile is a client-side Fabric mod for <strong>Minecraft Java 26.2 and 26.3</strong>.</p><ol><li>Install Fabric Loader <strong>0.20.1+</strong> and Fabric API for your Minecraft version.</li><li>Choose the matching Stockpile JAR below. Replace any older Stockpile JAR in your Minecraft <code>mods</code> folder, then launch the game.</li><li>Join your world and open a few chests. Run <code>/stockpile start</code>, then click <strong>Open dashboard</strong> in chat. The shortcut also prints the link. Automatic browser opening is off by default.</li></ol><div class="button-row">${state.source==='local'?button('close','Close','check','primary'):`<a class="button primary" href="./downloads/stockpile-0.3.2+26.2.jar" download>${icon('download',14)}Download for 26.2</a><a class="button" href="./downloads/stockpile-0.3.2+26.3.jar" download>${icon('download',14)}Download for 26.3</a>${button('import','Import inventory','upload')}`}</div><p class="small muted">Fabric API: <a href="https://modrinth.com/mod/fabric-api/versions?g=26.2" target="_blank" rel="noopener">26.2 versions</a> · <a href="https://modrinth.com/mod/fabric-api/versions?g=26.3" target="_blank" rel="noopener">26.3 versions</a>. Install one matching Stockpile JAR.</p><div class="modal-note">The connected dashboard runs on the same computer as Minecraft. For this hosted page, use <strong>Export inventory</strong> in the local dashboard, then import the JSON here. Hosted imports are snapshots; they do not sync automatically.<br><br>Inventory and schematic files stay in your browser or on your computer. No Minecraft login is needed.<br><br><code>/stockpile settings</code> controls the startup message, shortcut and automatic browser opening. <code>/stop</code> and <code>/stockpile stop</code> pause local tracking.</div><div class="modal-note"><strong>Build status:</strong> compiled against each supported Minecraft version. In-game behavior still needs a playtest.</div>`);}
function details(id){
  const row=allRows().find(r=>r.id===id)||{id,name:humanize(id),count:0,target:targets()[id]||0,locations:[]};
  modal(esc(row.name||humanize(id)),`<div class="details-summary">${itemImage(id)}<div><h3>${num(row.count)}</h3><p>items in ${row.locations.length} ${row.locations.length===1?'container':'containers'} · ${esc(dimensionLabel(state.dimension))}</p></div></div><p class="mono">${esc(id)}</p>${row.packedCount?`<p class="packed-summary">${num(row.looseCount||0)} loose · ${num(row.packedCount)} inside shulker boxes</p>`:''}${row.locations.map(c=>`<div class="detail-location"><div><h3>${esc(c.name)} ${c.placed?'<span class="placed-badge">PLACED SHULKER</span>':''}</h3><p>${esc(originLabel(c))} · ${esc(dimensionLabel(c.dimension))} · <span class="mono">${esc(c.position.join(' / '))}</span></p>${c.looseCount?`<p>${num(c.looseCount)} loose in this container</p>`:''}${(c.packedPaths||[]).map(p=>`<p class="packed-path">${num(p.count)} inside ${esc(p.path.join(' / '))}</p>`).join('')}<p>Checked ${ago(c.lastSeen)}</p></div><div class="right"><span class="number">${num(c.count)}</span>${button('copy-coord','Copy coords','copy','quiet small',`data-pos="${esc(c.position.join(' '))}"`)}</div></div>`).join('')||'<p>This item has not been observed in your selected storage.</p>'}<form class="target-form" id="target-form" data-id="${esc(id)}"><div><div class="field"><label for="target-amount">Low-stock target (0 turns tracking off)</label><input id="target-amount" type="number" min="0" max="${MAX_COUNT}" step="1" required value="${row.target}"></div><button class="button primary" type="submit">Save target</button></div></form>`);
}
function showTargets(){const t=targets();modal('Stock targets',`<p>Choose a minimum quantity for each supply. Items below it show as low stock; twice the target counts as plenty.</p><form id="targets-form">${Object.entries(t).filter(([,n])=>n>0).map(([id,n])=>`<label class="targets-row"><span>${itemImage(id)}</span><span class="target-label">${esc(humanize(id))}</span><input type="number" min="0" max="${MAX_COUNT}" step="1" value="${n}" data-target-id="${esc(id)}" aria-label="${esc(humanize(id))} minimum"></label>`).join('')||'<p>No stock targets yet. Add your first essential below.</p>'}<div class="field new-target"><label for="new-target-id">Add another item ID</label><input id="new-target-id" placeholder="minecraft:iron_ingot" pattern="[a-z0-9_.-]+:[a-z0-9_./-]+"></div><div class="field"><label for="new-target-count">Minimum quantity</label><input id="new-target-count" type="number" min="1" max="${MAX_COUNT}" step="1" value="64"></div><div class="modal-actions">${button('close','Cancel','','quiet')}<button type="submit" class="button primary">Save stock targets</button></div></form>`);}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function navigate(view){if(view==='ender'){state.containerKinds=['ender'];state.dimension='all';}else if(view==='inventory'){state.containerKinds=readLocal('stockpile-storage-kinds',STORAGE_KINDS).filter(k=>STORAGE_KINDS.includes(k));if(!state.containerKinds.length)state.containerKinds=[...STORAGE_KINDS];}writeLocal('stockpile-container-kinds',state.containerKinds);state.view=view;state.query='';state.filter='all';state.limit=20;state.mobile=false;render();window.scrollTo({top:0,behavior:'instant'});}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Coordinates copied.');}catch{modal('Chest coordinates',`<p>Select and copy:</p><div class="field"><input readonly value="${esc(text)}" aria-label="Coordinates"></div>`);}}
async function api(path,options={}){const r=await fetch(path,{cache:'no-store',...options,headers:{'X-Stockpile-Token':token,...options.headers}});if(!r.ok)throw new Error(r.status===401?'Run /stockpile start in Minecraft and click its new dashboard link.':`Minecraft connection returned ${r.status}.`);return r.json();}
let syncing=false;
async function sync(){
  if(!local||syncing)return;syncing=true;
  try{
    const data=validateSnapshot(await api('/api/snapshot'));
    const changed=JSON.stringify(data)!==JSON.stringify(state.data)||state.syncError;
    state.data=data;state.source='local';state.syncError='';
    if(!data.worlds.some(w=>w.id===state.worldId))state.worldId=data.worlds[0]?.id||'';
    if(changed)render();
    if(!state.registry){const registry=await api('/api/registry');if(registry&&Object.keys(registry).length)state.registry=registry;}
  }catch(e){if(state.syncError!==e.message){state.syncError=e.message;render();}}
  finally{syncing=false;}
}
async function importInventory(file){
  try{
    if(file.size>32*1024*1024)throw new Error('Inventory export exceeds 32 MB.');
    if(local)throw new Error('This dashboard shows your connected mod. Import exports into the hosted dashboard instead.');
    const data=validateSnapshot(JSON.parse(await file.text()));
    writeLocal('stockpile-inventory',data);state.data=data;state.source='import';state.worldId=data.worlds[0]?.id||'';state.dimension='all';state.query='';
    $('#modal').close();render();toast(`Imported ${data.worlds.reduce((s,w)=>s+w.containers.length,0)} containers.`);
  }catch(e){modal('Could not import inventory',`<p class="status-error">${esc(e.message)}</p><p>Use an unmodified Stockpile inventory JSON export.</p>${button('import','Choose another export','upload','primary')}`);}
}
async function uploadSchematic(file){
  if(state.busy)return;
  state.view='planner';state.busy=true;state.uploadError='';render();
  let worker;
  try{
    if(file.size>25*1024*1024)throw new Error('Maximum schematic upload size is 25 MB.');
    const buffer=await file.arrayBuffer();
    const parsed=await new Promise((resolve,reject)=>{
      worker=new Worker(new URL('./schematic-worker.js',import.meta.url),{type:'module'});
      const timer=setTimeout(()=>{worker.terminate();reject(new Error('This schematic took too long to read. Split it into smaller regions.'));},25000);
      worker.onmessage=({data})=>{clearTimeout(timer);data.ok?resolve(data.result):reject(new Error(data.error));};
      worker.onerror=()=>{clearTimeout(timer);reject(new Error('The schematic reader could not start in this browser. Try a current version of Safari, Chrome or Firefox.'));};
      worker.postMessage({buffer,filename:file.name,registry:state.registry},[buffer]);
    });
    const id=crypto.randomUUID();const entry={...parsed,id,filename:file.name,createdAt:Date.now()};
    state.projects.unshift(entry);state.projects=state.projects.slice(0,50);state.selectedProject=id;state.copies=1;state.missingOnly=false;
    writeLocal('stockpile-projects',state.projects);toast(`Added ${entry.name}.`);
  }catch(e){state.uploadError=e.message;toast('Schematic could not be read. See the message in Build planner.');}
  finally{worker?.terminate();state.busy=false;render();}
}
document.addEventListener('click',async e=>{
  const el=e.target.closest('[data-action]');
  if(!el){if(e.target.closest('#dropzone'))$('#schematic-file').click();return;}
  const action=el.dataset.action,id=el.dataset.id;
  if(action==='nav')navigate(el.dataset.view);
  else if(['planner','inventory'].includes(action))navigate(action);
  else if(action==='mobile'){state.mobile=!state.mobile;render();}
  else if(action==='connect')connect();
  else if(action==='recipe-toggle'){state.recipeSubstitutions=!state.recipeSubstitutions;writeLocal('stockpile-recipe-substitutions',state.recipeSubstitutions);render();}
  else if(action==='crafting-csv'){download('stockpile-crafting-steps.csv',craftingCsv(recipePlan()),'text/csv;charset=utf-8');}
  else if(action==='close')$('#modal').close();
  else if(action==='import')$('#inventory-file').click();
  else if(action==='upload')$('#schematic-file').click();
  else if(action==='export'){download(`stockpile-inventory-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state.data,null,2));toast(state.source==='demo'?'Exported example inventory.':'Inventory exported.');}
  else if(action==='filter'){state.filter=el.dataset.filter;state.limit=20;render();}
  else if(action==='reset-filters'){state.query='';state.filter='all';state.dimension='all';render();}
  else if(action==='more'){state.limit+=30;render();}
  else if(action==='details')details(id);
  else if(action==='targets')showTargets();
  else if(action==='copy-coord')await copy(el.dataset.pos);
  else if(action==='project'){state.selectedProject=id;state.copies=1;state.missingOnly=false;state.view='planner';render();window.scrollTo(0,0);}
  else if(action==='delete-project'){const p=project();modal('Remove this build?',`<p>Remove <strong>${esc(p.name)}</strong> and its saved material list from this browser?</p><div class="modal-actions">${button('close','Keep build','','quiet')}${button('confirm-delete-project','Remove build','trash','danger',`data-id="${esc(p.id)}"`)}</div>`);}
  else if(action==='confirm-delete-project'){state.projects=state.projects.filter(p=>p.id!==id);writeLocal('stockpile-projects',state.projects);state.selectedProject='';$('#modal').close();render();toast('Build removed.');}
  else if(action==='forget'){const c=world().containers.find(c=>c.id===id);modal('Forget this container?',`<p>Remove the saved contents of <strong>${esc(c.name)}</strong> at <span class="mono">${esc(c.position.join(' / '))}</span>? Open it again in Minecraft to track it again.</p><div class="modal-actions">${button('close','Keep record','','quiet')}${button('confirm-forget','Forget container','trash','danger',`data-id="${esc(id)}"`)}</div>`);}
  else if(action==='confirm-forget'){
    try{
      if(local){await api('/api/forget',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({worldId:state.worldId,containerId:id})});await sync();}
      else{world().containers=world().containers.filter(c=>c.id!==id);if(state.source==='import')writeLocal('stockpile-inventory',state.data);}
      $('#modal').close();render();toast('Saved container removed.');
    }catch(err){toast(err.message);}
  }else if(action==='export-materials'||action==='missing-csv'){
    const rows=comparison().filter(r=>action!=='missing-csv'||r.missing>0);
    download(`stockpile-${action==='missing-csv'?'missing':'materials'}.csv`,materialsCsv(rows),'text/csv;charset=utf-8');toast(action==='missing-csv'&&!rows.length?'All listed materials are available.':'Material checklist exported.');
  }else if(action==='about')modal('How counts work',`<p>Stockpile remembers the contents the server sends when you open a supported chest, barrel, shulker box or Ender Chest. Items inside shulker boxes are included by default. The item details show the parent chest and shulker slot. Player inventory and bundles are excluded.</p><p>Counts are grouped by item ID. Names, enchantments and other item components do not create separate material types. A double chest is one container. Your Ender Chest is counted once per world and player, and has its own view. Container-source checkboxes determine which totals and building materials are included. A PLACED badge marks items in shulker boxes placed in the world.</p><p>Your own item moves update automatically while a tracked container is open and when it closes. Closed chests can change without your client knowing. Reopen them to refresh, and remove old records if you move or break a container. Custom server menu plugins can change how containers behave.</p><p>Low-stock targets and uploaded build lists are saved in this browser. Exports let you back up inventory and material checklists.</p><div class="modal-note">Schematic checks compare direct placement materials. Recipe substitutions can also calculate vanilla crafting and stonecutting from the selected storage. The crafting plan shares ingredients across this build and reserves its directly required items first. It assumes access to the listed workstations. Smelting, fuel, custom server recipes, entities and container contents are not included. Supplies are not reserved between separate builds, and already-placed blocks are not verified. Review any import notes before gathering materials.</div>`);
});
document.addEventListener('input',e=>{
  if(e.target.id==='inventory-search'){state.query=e.target.value;state.limit=20;render();}
});
document.addEventListener('change',e=>{
  const el=e.target;
  if(el.id==='world-select'){state.worldId=el.value;state.dimension='all';state.query='';render();}
  else if(el.id==='dimension'){state.dimension=el.value;render();}
  else if(el.id==='sort'){state.sort=el.value;render();}
  else if(el.id==='recipe-version'){state.recipeVersion=el.value;writeLocal('stockpile-recipe-version',state.recipeVersion);render();}
  else if(el.id==='copies'){const n=Number(el.value);if(Number.isInteger(n)&&n>=1&&n<=999){try{compareMaterials(project().materials,inventory(),n);state.copies=n;}catch(err){toast(err.message);}}else toast('Choose between 1 and 999 copies.');render();}
  else if(el.matches('[data-container-kind]')){const kind=el.dataset.containerKind;state.containerKinds=el.checked?[...new Set([...state.containerKinds,kind])]:state.containerKinds.filter(k=>k!==kind);writeLocal('stockpile-container-kinds',state.containerKinds);const storage=state.containerKinds.filter(k=>k!=='ender');if(storage.length)writeLocal('stockpile-storage-kinds',storage);if(state.view==='ender'&&sourceScope(state.containerKinds)!=='ender')state.view='inventory';else if(state.view==='inventory'&&sourceScope(state.containerKinds)==='ender')state.view='ender';state.limit=20;render();}
  else if(el.id==='include-packed'){state.includePacked=el.checked;writeLocal('stockpile-include-packed',state.includePacked);render();}
  else if(el.id==='missing-only'){state.missingOnly=el.checked;render();}
  else if(el.id==='inventory-file'&&el.files[0])importInventory(el.files[0]);
  else if(el.id==='schematic-file'&&el.files[0])uploadSchematic(el.files[0]);
});
document.addEventListener('submit',e=>{
  if(e.target.id==='target-form'){
    e.preventDefault();const n=Number($('#target-amount').value);if(!Number.isInteger(n)||n<0||n>MAX_COUNT)return;
    const t=targets();if(n)t[e.target.dataset.id]=n;else delete t[e.target.dataset.id];writeLocal(targetKey(),t);$('#modal').close();render();toast('Stock target saved.');
  }else if(e.target.id==='targets-form'){
    e.preventDefault();const t=targets();for(const input of e.target.querySelectorAll('[data-target-id]')){const n=Number(input.value);if(n)t[input.dataset.targetId]=n;else delete t[input.dataset.targetId];}
    const id=$('#new-target-id').value.trim(),n=Number($('#new-target-count').value);if(id){if(!validId(id)||!Number.isInteger(n)||n<1||n>MAX_COUNT){toast('Enter a valid item ID and minimum quantity.');return;}t[id]=n;}
    writeLocal(targetKey(),t);$('#modal').close();render();toast('Stock targets saved.');
  }
});
document.addEventListener('keydown',e=>{
  if(e.key==='/'&&!$('#modal').open&&!['INPUT','TEXTAREA'].includes(e.target.tagName)){e.preventDefault();$('#inventory-search')?.focus();}
  if((e.key==='Enter'||e.key===' ')&&e.target.id==='dropzone'){e.preventDefault();$('#schematic-file').click();}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render();
if(local){sync();setInterval(sync,2500);}

document.addEventListener('error',e=>{const el=e.target;if(el instanceof HTMLImageElement&&!el.src.endsWith('/ui/unknown.svg')){el.src='./ui/unknown.svg';}},true);
